INSERT INTO characters (slug,name,team,creator,owner_id,tags,appears_in,data,status,url_slug,created_at,updated_at) VALUES
('stowaway-the-menagerie','Stowaway','outsider','Goodpart',NULL,NULL,'The Menagerie','{"slug":"stowaway-the-menagerie","name":"Stowaway","team":"outsider","ability":"You do not know you are the Stowaway. You think you are an in-play Outsider, but you are not. [+0 or +1 Outsider]","creator":"Goodpart","appearsIn":"The Menagerie","quote":"Gods above, this crate is heavy!","lede":"The Stowaway sows discord among Outsiders by claiming to be one of them.","howToRun":["Consider giving the Stowaway to Outsiders who can “fail” to operate in some fashion in order to assist the town in figuring out who the Stowaway actually is."],"tips":["Like the Drunk, you won’t know you’re the Stowaway, and will need to find it out via gameplay. This may be impossible depending on the role you receive, but rest assured that for the most part, while your ability won’t impact the game, nor will it detract: meaning that if you’re a role like the Damsel, Recluse or Saint, the downside of your ability doesn’t apply. So hey, there’s that. Moreover, if you have some way of confirming you are the Stowaway, you can play as an outed Damsel, and see if any evil players take the bait!"],"bluffing":["Bluffing as a Stowaway isn’t terribly different to bluffing as a Drunk. Your claim may need to be backed up by a Librarian, so if you’re either lucky enough to be a Minion in a Librarian ping, or have Librarian in the pocket as a bluff, you can use it to sell a world where a Stowaway exists. Bluffing as an Outsider whose power can fail publicly, like the Moonchild, can definitely assist in selling your real role as the Stowaway. If you have a source of poisoning, you may also be able to sell that the Stowaway is in play by poisoning an Outsider at the point they are meant to trigger."],"fighting":[],"examples":["Claire is the Stowaway, but they think they are the Saint. They are executed on Night 5, but the game does not end. Oops.","Jon is the Baron claiming to be the Saint, even though there is a Saint in play. Jon claims to have been seen as the Saint by a Ravenkeeper, and town executes the real Saint. Oops."],"firstNight":0,"firstNightReminder":"","otherNight":0,"otherNightReminder":"","reminders":[],"remindersGlobal":["Is The Stowaway"],"setup":true,"special":[{"name":"replace-character","type":"reveal"},{"name":"bag-disabled","type":"selection"}],"jinxes":[{"name":"Drunk","align":"good","text":"The Drunk cannot be a Stowaway.","id":"drunk"}],"image":"https://menagerie.towerrangers.net/images/stog.png","curata":false,"imageAlt":"https://menagerie.towerrangers.net/images/stoe.png"}','published','the-menagerie/stowaway',datetime('now'),datetime('now')),
('thrall','Thrall','outsider','Goodpart',NULL,NULL,'The Menagerie','{"slug":"thrall","name":"Thrall","team":"outsider","ability":"Once per game, a Minion may give you a task for the next day. If you reveal the task, or 5 or more players live and you fail by dusk, the Demon gains a Minion ability.","creator":"Goodpart","appearsIn":"The Menagerie","quote":"Evil doesn''t always look like a monster. Sometimes, it just looks like someone following orders.","lede":"The Thrall must carry out its master''s bidding, lest it strengthen the evil team.","howToRun":["Make sure to moderate the task a Minion gives to ensure that it is passable, and within the spirit of the game. Putting the Thrall in an unwinnable situation, or one that might cause awkwardness for other players is never the way to go."],"tips":["Oh dear. As the Thrall, you have the unfortunate honour of carrying out a task handed to you by your master - a Minion. It''s likely that a Minion will send you this task early, but they can always hold on to it until later. You can always try to get yourself executed before you''re tasked to carry out your master''s will, but this may be equally attractive to a Godfather, so consider your options. Just hope that you''re dead by the time your Minion wants to give you a task.","Once your task has been handed to you, remember that death isn''t an escape: you have exactly one day to complete your task to the Storyteller''s satisfaction, so taking the easy out of requesting execution won''t do it."],"bluffing":["Simply put, bluffing as the Thrall allows you to play outed evil, if only for a day. Anything outrageous you might do to sow chaos or just spread misinformation can be reliably covered by claiming to be the Thrall later. It''s possible the good team may simply leave you alone afterwards. You may even want to consider spreading true information about the game state under the presumption that because it''s being stated by a Thrall, it must be false. How you bluff this role is up to you, really.","If you are a Minion who has received a Thrall, tasks might include prompting another player to say the Mezepheles'' word while you sit in town, nominating and sincerely accusing a powerful Townsfolk, or asking the Thrall to pass false information about the evil team to another good player, framing them. And if the good team has cottoned on to this strategy, why not simply ask the Thrall to provide another member of the evil team with a number of claims from town to an actual evil player? No-one will believe them anyway, right?"],"fighting":[],"examples":["Lee is the Thrall. On Night 2, they are tasked with asking a certain player: \"Who wrote Hamlet?\" - that player answers \"Shakespeare\", which is the Mezepheles'' word.","Drew is the Goblin bluffing as the Thrall. On Day 3, they out the Ravenkeeper publicly and claim to be the Goblin. On Day 4, they note that this was simply their Thrall task, which they thankfully succeeded!"],"firstNight":45,"firstNightReminder":"Inform a Minion of your choice that the Thrall is in play. Wake that Minion and ask if they wish to give the Thrall a task.","otherNight":45,"otherNightReminder":"Wake the Minion that learned of a Thrall and ask if they wish to give the Thrall a task. If the Thrall failed or revealed their task, inform the Demon of the Minion ability they have gained.","reminders":["Tasked","Knows"],"setup":false,"jinxes":[{"name":"Evil Twin","align":"good","text":"The Demon cannot gain the Evil Twin ability.","id":"eviltwin"},{"name":"Goblin","align":"good","text":"If the Thrall fails their task, a living Minion gains the Goblin ability in addition to their own ability, and learns this.","id":"goblin"},{"name":"Scarlet Woman","align":"good","text":"If the Thrall fails their task, a living Minion gains the Scarlet Woman ability in addition to their own ability, and learns this.","id":"scarletwoman"},{"name":"Boomdandy","align":"good","text":"If the Thrall fails their task, a living Minion gains the Boomdandy ability in addition to their own ability, and learns this.","id":"boomdandy"},{"name":"Baron","align":"good","text":"If the Thrall fails their task, a living Townsfolk becomes the Thrall.","id":"baron"},{"name":"Marionette","align":"good","text":"If the Demon has a neighbour who is alive and a Townsfolk or Outsider when the Thrall has failed their task, that player becomes an evil Marionette. If there is already an extra evil player, this does not happen.","id":"marionette"},{"name":"Doppelganger","align":"good","text":"If the Thrall fails their task, a living Minion gains the Doppelganger ability in addition to their own ability, and learns this.","slug":"doppelganger-the-menagerie"},{"name":"Lady Lace","align":"good","text":"If the Thrall fails their task, a living Minion gains the Lady Lace ability in addition to their own ability, and learns this.","slug":"lady-lace"}],"image":"https://menagerie.towerrangers.net/images/thrg.png","curata":false,"imageAlt":"https://menagerie.towerrangers.net/images/thre.png"}','published','the-menagerie/thrall',datetime('now'),datetime('now')),
('yang','Yang','outsider','Goodpart',NULL,NULL,'The Menagerie','{"slug":"yang","name":"Yang","team":"outsider","ability":"If you are good, you might not die. Each night, choose a player different to last night: if good, they cannot die, but are drunk until dusk. If you are ''mad'' about being an Outsider, you might be executed, even if dead.","creator":"Goodpart","appearsIn":"The Menagerie","quote":"Water seeks to quench fire, but it must not linger, lest it boil.","lede":"The Yang is part of a delicate dance with the Yin, protecting, drunkening, but never outing, always waiting to turn evil.","howToRun":["Use discretion if the Yang outs their role. Players who out themselves as the Yang may be doing so to ensure they are executed (and therefore no longer in play). If there is a Yin in play, keeping them alive in this way ensures that the Yin is aware that they exist, and provides a sizeable advantage to the evil team. Similarly, this opens avenues for other players to “claim” to be the Yang and not die, which in turn may cause the Yin to second guess who their partner is."],"tips":["You are an Outsider that can never claim to be an Outsider. As such, you’ll need to come up with a convincing bluff, and potentially sell that bluff the entire game. Claiming to be the Yang, or any Outsider at any point may lead to your execution, even if you are dead, so be very careful about what you say, and to whom. Your protection role is double-edged: on one hand, players you select can’t die at night, but they are also drunk. You can’t inform them of this, but it may be useful to suggest that chosen players need to question their information, or not bank on specific abilities working as intended.","As an evil Yang, your role doesn’t change much, however now that you know your Yin, you can coordinate your actions and be an effective force for evil, setting up frames, poisoning information, and generally causing trouble around town.","Crucially, as the Yang, be prepared at any time to become the dreaded Yin-Yang: if you do, you’ll become known to the Yin, and can push towards the end game - so don’t arouse suspicion, and be aware that you could become a prime target for execution later on."],"bluffing":["Never claim to be the Yang! The nature of the character is such that you would never want to alert people to your real role, so play cautiously, and offer reasons as to any double claims or misaligned information."],"fighting":[],"examples":["Belle is the Yang. They are executed on Day 1 but do not die. They claim to be the Soldier, the Pacifist, the Devil''s Advocate, anything - just not the Yang.","Iris is the Devil''s Advocate. They don''t claim to be the Yang, ever. Everyone stops asking questions they don''t want the answer to."],"firstNight":30,"firstNightReminder":"The Yang chooses a player.","otherNight":31,"otherNightReminder":"The Yang chooses a player.","reminders":["Safe & Drunk"],"setup":false,"jinxes":[{"name":"Marionette","align":"good","text":"The Marionette can neighbour the Yang.","id":"marionette"}],"image":"https://menagerie.towerrangers.net/images/yang.png","curata":false,"imageAlt":"https://menagerie.towerrangers.net/images/yane.png"}','published','the-menagerie/yang',datetime('now'),datetime('now')),
('arbiter-the-menagerie','Arbiter','minion','Goodpart',NULL,NULL,'The Menagerie','{"slug":"arbiter-the-menagerie","name":"Arbiter","team":"minion","ability":"Each night, you may make a unique rule until dusk, agreed to by the Storyteller. If a good player breaks that rule, at night, choose a player: they die.","creator":"Goodpart","appearsIn":"The Menagerie","quote":"I am the law, so, I won. (Creator credit: Mega)","lede":"The Arbiter makes rules good players need to follow the next day, and punishes those who break them.","howToRun":["As with a Wizard wish, be sure to moderate the rules the Arbiter creates so that they fit with the spirit of the game, and aren''t overly unfair."],"tips":["Who doesn''t want to make the rules?","As the Arbiter, you get to torment the good team with rules they have to follow. These can be serious and restrictive, like asking that players only nominate neighbours, or that players cannot claim their actual role; or they can be chaotic and whimsical, like needing to include animal noises in any public statements. It''s entirely up to you.","Both strategies are perfectly valid, and good players are equally likely to break rules in either respect, so have fun with it, and secure those kills whenever you can.","Make sure that your evil team also follows the rules so that they don''t out themselves, and perhaps consider killing an already dead player in the event that someone does break a rule to frame them instead."],"bluffing":[],"fighting":["Look for people who break the rules! Evil players don''t have to follow the Arbiter''s rules, so breaking them won''t result in extra kills. If this happens, it''s possible you''ve found an evil player.","Otherwise, so long as you follow the rules, no-one gets hurt, right? Be diligent, and follow the rules as best as possible."],"examples":["Gale is the Arbiter. He asks the Storyteller to make a rule stating that players must only claim evil roles the next day. The Storyteller announces this rule the next day. The Tea Lady accidentally claims their actual role: the Arbiter is granted a kill during the night.","Nathen is the Recluse who follows the rule of thanking the person they nominate. They notice that Minnie did not say thank you at the end of their nomination, but no extra kill occurs during the night. Nathen correctly infers that Minnie is evil."],"firstNight":30,"firstNightReminder":"Negotiate a rule with the Arbiter. Once agreed, announce it during the night. It takes effect immediately.","otherNight":30,"otherNightReminder":"The Arbiter selects a player to kill if a rule was broken. Negotiate a rule with the Arbiter. Once agreed, announce it during the night. It takes effect immediately.","reminders":["Rule","Rule","Rule","Rule","Rule","Penalty"],"setup":false,"jinxes":[{"name":"Zealot","align":"good","text":"If the Arbiter''s rule would conflict with the Zealot''s ability, the Zealot is deemed to not have broken a rule.","id":"zealot"},{"name":"Butler","align":"good","text":"If the Arbiter''s rule would conflict with the Butler''s ability, the Butler is deemed to not have broken a rule.","id":"butler"},{"name":"Golem","align":"good","text":"If the Arbiter''s rule would conflict with the Golem''s ability, the Golem is deemed to not have broken a rule.","id":"golem"},{"name":"Thrall","align":"good","text":"If the Arbiter''s rule would conflict with the Thrall''s task, the Thrall is deemed to not have broken a rule.","slug":"thrall"},{"name":"Alchemist","align":"good","text":"The Alchemist registers as evil to their own ability.","id":"alchemist"}],"image":"https://menagerie.towerrangers.net/images/taske.png","curata":false,"imageAlt":"https://menagerie.towerrangers.net/images/taskg.png"}','published','the-menagerie/arbiter',datetime('now'),datetime('now')),
('blackmailer','Blackmailer','minion','Goodpart',NULL,NULL,'The Menagerie','{"slug":"blackmailer","name":"Blackmailer","team":"minion","ability":"Each night, choose two players. The first must vote with the second. If they do not, one or both might die.","creator":"Goodpart","appearsIn":"The Menagerie","quote":"Even the most honourable person is forced to yield to blackmail once or twice in their life, if only to keep the peace. (Creator credit: Matt)","lede":"The Blackmailer forces a player to vote with another, with potentially lethal consequences if they don''t.","howToRun":["While players can out that they have been blackmailed, be judicious about killing players who don''t follow the restriction placed upon them."],"tips":["As the Blackmailer, you have the ability to tie together the votes of two players. How you do this is up to you. Perhaps you may want to bind one player with a correct read on the evil team to someone who is convinced of a very different - wrong - world; or maybe you''ll force someone to vote for an evil player? How you play the Blackmailer really depends on what objective you wish to achieve, but with the penalty for not voting in line with the tethered player being death, players will be eager to follow along."],"bluffing":[],"fighting":["Simply put, don''t break the one golden rule. Voting with the player you''ve been forced to align with is the best - and only - way to guarantee the Blackmailer doesn''t kill you and the player you''re bound to.","If you think you can spare it, and you are truly of the belief that you have the evil team dead to rights, consider breaking your chains and risk death. You''re still free to vote as you please, albeit with consequences if it doesn''t coincide with the player you''ve been tied to."],"examples":["Brennan is the Blackmailer. He forces the Balloonist to vote with the Zealot. The Balloonist must now vote on every nomination per the Zealot''s ability.","Liam is the Engineer, who is told during the night he must vote with his neighbour. His neighbour - who Liam believes is evil - is voting with the evil team he has built. Liam breaks with his neighbour''s voting pattern. Liam dies, but his neighbour does not."],"firstNight":30,"firstNightReminder":"The Blackmailer chooses two players. Place the ''First'' token on the first player chosen, and the ''Second'' token on the second player chosen.","otherNight":30,"otherNightReminder":"The Blackmailer chooses two players. Place the ''First'' token on the first player chosen, and the ''Second'' token on the second player chosen.","reminders":["First","Second"],"setup":false,"jinxes":[{"name":"Zealot","align":"good","text":"The Zealot, if forced to vote with another player, must still adhere to their own ability. Neither the Zealot or the Blackmailer''s other target die as a result.","id":"zealot"},{"name":"Butler","align":"good","text":"The Butler, if forced to vote with another player, must still adhere to their own ability. Neither the Butler or the Blackmailer''s other target die as a result.","id":"butler"}],"image":"https://menagerie.towerrangers.net/images/ablae.png","curata":false,"imageAlt":"https://menagerie.towerrangers.net/images/ablag.png"}','published','the-menagerie/blackmailer',datetime('now'),datetime('now')),
('chatterpox','Chatterpox','minion','Goodpart',NULL,NULL,'The Menagerie','{"slug":"chatterpox","name":"Chatterpox","team":"minion","ability":"Minion and Demon abilities may be falsely shown or announced to players. They may malfunction in some way.","creator":"Goodpart","appearsIn":"The Menagerie","quote":"Hey Gerald, didja ever hear the one about the beermonger hiding as the town''s innkeeper? They called him the fearmonger! Wait, is that how it goes? Hey, you try gettin'' the words out right with a hand up your--","lede":"The Chatterpox causes chaos by revealing Minion abilities that may - or may not - exist.","howToRun":["As a general rule, don''t go overboard. The Chatterpox is a Minion, and should cause chaos, but too many false announcements can cause an unfun experience. For instance, announcing every possible Minion or Demon ability at night in a 1 Minion game makes the game nearly unsolvable for the good team.","With that said, if the timing is right, going overboard might be just the thing to spice up a game and give town the information they need to swing the game back in their favour. For instance, if town is convinced a Chatterpox is not in play, why not make them all \"Cerenovus mad\" as the same role, knowing a Cerenovus isn''t in play?","Examples of false announcements would include Cerenovus madness, Harpy madness, Arbiter rules, Al Hadikhia announcements, Fearmonger picks, etc: anything that reveals itself in the process of operating is valid as part of the Chatterpox''s ability.","Malfunctions can be varied in nature: the Al Hadikhia picking 2 or 4 players, the Fearmonger choosing the same target, the Harpy making someone mad at themselves, or even the Storyteller. Be creative!"],"tips":["Sit back and enjoy.","No, seriously - so long as you stay alive, your ability is working, so let the chaos unfold around you. The Storyteller controls how your ability functions, so it may be subtle, it may be obvious, but it''s always working. To aid in the process, perhaps try to convince your evil team to play into it, and make up false information of their own. This all but confirms that a Chatterpox is in play, but it does lend them some credibility, and might even be the only instance of that sort of announcement, if talking about Cerenovus madness, Harpy madness, and so on.","If a Chatterpox isn''t in play, you can always simulate it by making up fake night cards - but beware: good players have no reason to do this, and so if it''s ever puzzled out that a Chatterpox isn''t in play, you might find yourself under suspicion."],"bluffing":[],"fighting":["Be cautious about what you reveal about how you were impacted by evil abilities at night. You may not be Cerenovus mad, but who''s to say you definitely aren''t? Wait until the day after you''re freed to announce your madness - which in turn might give other players incentive to reveal the same. It''s likely that if claims about being affected by Minion abilities don''t stack up, a Chatterpox is in play, but of course, it could also be a bluff from evil players.","Keep an open mind, and be attentive. If a Storyteller gives you a night card or makes an announcement that seems like it may have been sent in error, unless the Storyteller corrects it, chances are it''s a Chatterpox, and it''ll be on your shoulders to let town know. An eye for detail is crucial in determining whether what you''ve seen is real or not."],"examples":["Jordan is the Chatterpox with a Cerenovus as their fellow Minion, and a Fang Gu as their Demon. During the night, the \"Fearmonger\" selects a player, and two players are told they are mad by the Cerenovus: only one of them is real. The next day, the player that really is mad breaks Cerenovus madness thinking it to be a Chatterpox, and is executed.","Devon is the Recluse who is told they have been selected by the Kazali to be the Widow. They do not see the Grimoire, nor do they learn who their team is. The Poppy Grower dies on Day 3, but Devon still learns nothing. They realise they were falsely picked by the Chatterpox."],"firstNight":19,"firstNightReminder":"Show, or announce a Minion or Demon ability as they would normally: you may break the rules or change the phrasing of these abilities.","otherNight":8,"otherNightReminder":"Show, or announce a Minion or Demon ability as they would normally: you may break the rules or change the phrasing of these abilities.","reminders":[],"setup":false,"image":"https://menagerie.towerrangers.net/images/dume.png","curata":false,"imageAlt":"https://menagerie.towerrangers.net/images/dumg.png"}','published','the-menagerie/chatterpox',datetime('now'),datetime('now')),
('counterfeiter','Counterfeiter','minion','Goodpart',NULL,NULL,'The Menagerie','{"slug":"counterfeiter","name":"Counterfeiter","team":"minion","ability":"On Nights 1 and 2, you see the Grimoire, with characters removed: you may move 1 unique reminder token in play.","creator":"Goodpart","appearsIn":"The Menagerie","quote":"If you''re not cheating, you''re not trying. (Creator credit: George)","lede":"The Counterfeiter wields reminder tokens like a weapon, forging evidence out of thin air.","howToRun":["Be sure to place all relevant reminder tokens at the start of the game so that the Counterfeiter can move them as necessary."],"tips":["Under construction!"],"bluffing":[],"fighting":["Under construction!"],"examples":["George is the Counterfeiter. On Night 2, upon learning the Lleech host is the Noble, he moves the Lleech poison to the player he believes to be the Barber, while also making the Baron the Fortune Teller''s Red Herring, and moving the Cannibal''s reminder token to who he believes is the Drunk.","Dara is the Juggler. They juggle the Washerwoman, Noble and Fortune Teller successfully, but their info seems wrong. They can infer that the Counterfeiter is likely in play, and that their information is in some way corrupted."],"firstNight":32.5,"firstNightReminder":"Remove characters from the Grimoire (including bluffs) and show the Counterfieter the Grimoire. They may move 1 unique reminder token they see.","otherNight":38.5,"otherNightReminder":"Remove characters from the Grimoire (including bluffs) and show the Counterfieter the Grimoire. They may move 1 unique reminder token they see.","reminders":[],"setup":false,"special":[{"type":"signal","name":"grimoire","time":"night"}],"jinxes":[{"name":"Cannibal","align":"good","text":"If the Counterfeiter moves the Lunch token to an evil player, it becomes the Cannibal''s Poisoned token.","id":"cannibal"},{"name":"Marionette","align":"good","text":"If the Counterfeiter moves the Is The Marionette token from the evil Marionette to a good player, that player becomes the evil Marionette: the previous Marionette turns good and regains their ability.","id":"marionette"},{"name":"Cerenovus","align":"good","text":"If the Counterfeiter moves the Mad token, the player it moves to is informed that they are mad as the character the Cerenovus chose.","id":"cerenovus"},{"name":"Harpy","align":"good","text":"If the Counterfeiter moves the Mad token, the player it moves to is informed that they are mad at the same player the Harpy chose. If they move the 2nd token, the player with the Mad token is informed their target has changed.","id":"harpy"},{"name":"Blackmailer","align":"good","text":"If the Counterfeiter moves the First token, the player it moves to is informed that they must vote with the same player the Blackmailer chose. If they move the Second token, the player with the First token is informed their target has changed.","slug":"blackmailer"}],"image":"https://menagerie.towerrangers.net/images/coue.png","curata":false,"imageAlt":"https://menagerie.towerrangers.net/images/coug.png"}','published','the-menagerie/counterfeiter',datetime('now'),datetime('now')),
('crook-the-menagerie','Crook','minion','Goodpart',NULL,NULL,'The Menagerie','{"slug":"crook-the-menagerie","name":"Crook","team":"minion","ability":"Nominations are not public, and are instead given privately to the Storyteller during the day. Each night*, learn players who nominated evil, & you may make yourself drunk until dusk.","creator":"Goodpart","appearsIn":"The Menagerie","quote":"Citizens - your vote counts! This is democracy inaction! Oh ho, did I say ''inaction''? A mere slip of the tongue, I assure you. Now, if you''ll cast your votes in these booths... do mind the gap.","lede":"The Crook keeps nominations secret, and learns about who nominated.","howToRun":["Announce that the Crook is in play at the start of each day, if sober. For the rest of the day, people can approach you privately to note their nomination, and nominations run in the order they were given to you, skipping any invalid nominations (ie. a nomination on a previously nominated player).","The Crook receives all information on who nominated who, even nominations that didn''t occur due to being rendered invalid.","All effects of nominations, such as the Virgin''s ability, the Witch''s ability, etc, should be carried out at the end of the day, after all nominations are exhausted.","For brevity, consider running only defense and pertinent information."],"tips":["The Crook is to nominations what the Organ Grinder is to votes - it obscures and conceals what is otherwise readily visible, learning all of the hot gossip at night. The Crook, therefore, is a useful tool in an evil toolkit to ensure evil players can push on good players with impunity, and can learn where town''s suspicions might lie. You can use this information to find serial nominators for a Witch to kill later, get a sense of what sorts of conclusions have been drawn from private conversations, and see who''s on the right track first, as they may be privy to information others simply don''t have.","Generally, though, as long as you choose to be sober, you''re doing your job - but if you''re looking to frame a specific player as the Crook, drunkening yourself at night might be just the thing to sway a game."],"bluffing":[],"fighting":["Have you ever approached the Storyteller faking an Artist question? Of course you have. Now you have a new reason to harass the Storyteller - nominations! Perhaps you''d like to submit your nomination first in the day to ensure it''s heard in full, or perhaps you''ll want to go last to make sure town gives it the closest attention. Consider where the information lies and who is liable to nominate, as the order plays out in order of requests per day. You may even want to consider going to the Storyteller only to not nominate at all, just to see if the evil team is watching you, or giving them the impression you''re sitting on damning information that you don''t really have. Remember that the Crook, unless sat next to the Demon, can''t relay who nominated who, so information is almost always going to be slightly delayed. Use it to your advantage."],"examples":["Mathilde is the Crook. She chooses to stay sober on Night 1, and the day is carried out per the Crook''s ability. At night, she learns that four players nominated the claimed Klutz, and only one player - the Fortune Teller - nominated the Demon.","James is the Washerwoman confirming the Dreamer, who has seen the Demon as either the Pixie or the Po. James, learning this information, immediately approaches the Storyteller and opts to nominate them. Upon learning this the following night, the Crook passes this info on to the Po, who kills James, thinking them to be a powerful information role. Thanks for your sacrifice, James."],"firstNight":30,"firstNightReminder":"The Crook may choose to make themselves drunk until the following night. Announce the Crook is in play at Dawn if the Crook is sober.","otherNight":30,"otherNightReminder":"Show the Crook the player(s) who nominated evil players today. The Crook may choose to make themselves drunk until the following night. Announce the Crook is in play at Dawn if the Crook is sober.","reminders":["Drunk"],"setup":false,"jinxes":[{"name":"Town Crier","align":"good","text":"The Town Crier learns one player who nominated along with their usual information.","id":"towncrier"},{"name":"Witch","align":"good","text":"Players who would die by the Witch''s ability die along with the day''s executee.","id":"witch"},{"name":"Golem","align":"good","text":"Players who would die by the Golem''s ability die along with the day''s executee.","id":"golem"},{"name":"Virgin","align":"good","text":"Players who would die by the Virgin''s ability die instead of the day''s executee.","id":"virgin"},{"name":"Gerrymanderer","align":"good","text":"If the Gerrymanderer is in play, only one evil nomination counts towards its ability.","slug":"gerrymanderer"}],"image":"https://menagerie.towerrangers.net/images/croe.png","curata":false,"imageAlt":"https://menagerie.towerrangers.net/images/crog.png"}','published','the-menagerie/crook',datetime('now'),datetime('now'));